"""Recorder for the server<->client intraday BUCKET-GRID parity fixture (P0 rails).

Writes ``tests/fixtures/bar_bucket_grid_2026.json``: every bucket start/end the
SERVER's one bucket helper — ``api.services.bar_rollup.tv_bucket_bounds`` — draws
for tf 1/5/15/30/60 on both grids (``rth`` = TradingView session-anchored 60m,
``eth`` = clock hours) across the full ET extended window 04:00-20:00 of EVERY
calendar day of 2026 (incl. both DST transitions, Mar 8 and Nov 1, and the NYSE
13:00 half-days).

Two rails read it:
  * ``tests/test_bucket_grid_parity.py`` — the server still draws exactly this
    grid (drift detector) AND the grid obeys the bucket contract stated in general
    form (contiguous, on-period, 60m never spans the 09:30 open or the close, ET
    offset follows DST) — so a fixture regenerated from a broken server fails too.
  * ``app/src/components/chart/rails/bucketGridParity.test.js`` — the CLIENT's
    ``chart/barTime.bucketStartUnix`` / ``chart/liveBuckets.bucketEndUnix`` /
    ``bucketEndChartTime`` / ``computeBarTime`` produce the identical buckets.

Encoding (per day, per "tf/session"): run-length list of
``[start_min, len_min, count]`` where ``start_min`` is minutes after ET midnight;
``count`` consecutive buckets of ``len_min`` minutes. ``base`` is the unix second
of 04:00 ET that day, so bucket start unix = base + (start_min - 240) * 60 (no US
DST change ever happens inside 04:00-20:00).

Regenerate ONLY for an intentional grid change (owner ruling), from the repo root:
    .venv/Scripts/python tests/fixtures/_gen_bucket_grid.py
and say why in the commit. Re-recording to make a red parity test green converts a
real server/client divergence into a green build.
"""

from __future__ import annotations

import json
import os
import sys
from datetime import date, datetime, timedelta

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

YEAR = 2026
TFS = ("1", "5", "15", "30", "60")
SESSIONS = ("rth", "eth")
WINDOW_START_MIN = 4 * 60     # 04:00 ET
WINDOW_END_MIN = 20 * 60      # 20:00 ET (exclusive)
FIXTURE_PATH = os.path.join(ROOT, "tests", "fixtures", "bar_bucket_grid_2026.json")


def _et():
    from zoneinfo import ZoneInfo
    return ZoneInfo("America/New_York")


def _rle(buckets: list[tuple[int, int]]) -> list[list[int]]:
    """[(start_min, end_min)] contiguous -> [[start_min, len, count]]."""
    out: list[list[int]] = []
    for s, e in buckets:
        ln = e - s
        if out and out[-1][1] == ln and out[-1][0] + out[-1][1] * out[-1][2] == s:
            out[-1][2] += 1
        else:
            out.append([s, ln, 1])
    return out


def day_grid(d: date) -> dict:
    from api.services.bar_rollup import tv_bucket_bounds
    from api.services.nyse_calendar import NYSE_EARLY_CLOSES_YYYYMMDD

    et = _et()
    base_dt = datetime(d.year, d.month, d.day, WINDOW_START_MIN // 60, 0, tzinfo=et)
    base = int(base_dt.timestamp())
    off_min = int(base_dt.utcoffset().total_seconds() // 60)
    grids: dict[str, list[list[int]]] = {}
    for tf in TFS:
        for sess in SESSIONS:
            buckets: list[tuple[int, int]] = []
            m = WINDOW_START_MIN
            while m < WINDOW_END_MIN:
                probe_ms = (base + (m - WINDOW_START_MIN) * 60) * 1000
                s_ms, e_ms = tv_bucket_bounds(probe_ms, tf, sess)
                s_min = (s_ms // 1000 - base) // 60 + WINDOW_START_MIN
                e_min = (e_ms // 1000 - base) // 60 + WINDOW_START_MIN
                if not (s_min <= m < e_min):
                    raise AssertionError(f"{d} {tf}/{sess}: minute {m} outside its own bucket {s_min}-{e_min}")
                buckets.append((s_min, e_min))
                m = e_min
            grids[f"{tf}/{sess}"] = _rle(buckets)
    return {
        "date": d.isoformat(),
        "base": base,
        "utc_offset_min": off_min,
        "half_day": (d.year * 10000 + d.month * 100 + d.day) in NYSE_EARLY_CLOSES_YYYYMMDD,
        "grids": grids,
    }


def build() -> dict:
    days = []
    d = date(YEAR, 1, 1)
    while d.year == YEAR:
        days.append(day_grid(d))
        d += timedelta(days=1)
    return {
        "//": [
            "Server<->client intraday bucket-grid parity fixture (P0 rails). GENERATED by",
            "tests/fixtures/_gen_bucket_grid.py from api.services.bar_rollup.tv_bucket_bounds.",
            "grids['tf/session'] = [[start_min_after_ET_midnight, len_min, count], ...] covering 04:00-20:00 ET.",
            "base = unix second of 04:00 ET that date. Do not hand-edit; regenerate only for an owner-approved grid change.",
        ],
        "year": YEAR,
        "window_min": [WINDOW_START_MIN, WINDOW_END_MIN],
        "tfs": list(TFS),
        "sessions": list(SESSIONS),
        "days": days,
    }


def dumps(doc: dict) -> str:
    # One day per line: diffable, compact.
    head = {k: v for k, v in doc.items() if k != "days"}
    lines = json.dumps(head, indent=1)[:-2]
    body = ",\n".join("  " + json.dumps(day, separators=(",", ":")) for day in doc["days"])
    return lines + ',\n "days": [\n' + body + "\n ]\n}\n"


if __name__ == "__main__":
    doc = build()
    with open(FIXTURE_PATH, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(dumps(doc))
    print(f"wrote {FIXTURE_PATH}: {len(doc['days'])} days")
